    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            edges = set()

            while q:
                x, y = q.popleft()
                cells.append((x, y))
                if x == 0: edges.add("top")
                if x == h - 1: edges.add("bottom")
                if y == 0: edges.add("left")
                if y == w - 1: edges.add("right")

                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w
                            and grid[nx][ny] == bg and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))

            # Fill nontrivial enclosed pockets, including pockets sealed
            # against one edge of the grid.
            if len(cells) >= 2 and len(edges) <= 1:
                for x, y in cells:
                    out[x][y] = 4

    return out
